package com.smartapproval.service;
import com.smartapproval.domain.*; import com.smartapproval.dto.*; import com.smartapproval.exception.InvalidDecisionException; import com.smartapproval.repository.PurchaseRequestRepository; import org.junit.jupiter.api.*; import org.mockito.*; import java.math.BigDecimal; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class PurchaseRequestServiceTest { PurchaseRequestRepository repo=mock(PurchaseRequestRepository.class); PurchaseRequestService service=new PurchaseRequestService(repo); @BeforeEach void setup(){when(repo.save(any())).thenAnswer(i->i.getArgument(0));}
 @Test void autoApprovesAtLimit(){assertEquals(RequestStatus.APROBADA,service.create(dto("1000000")).status());} @Test void leavesHighAmountPending(){assertEquals(RequestStatus.PENDIENTE,service.create(dto("1000000.01")).status());}
 @Test void preventsRepeatedDecision(){var p=new PurchaseRequest(UUID.randomUUID(),"Ana","a@b.co","X","D",BigDecimal.ONE,"CC",RequestStatus.APROBADA,java.time.Instant.now());when(repo.findById(p.getId())).thenReturn(Optional.of(p));assertThrows(InvalidDecisionException.class,()->service.approve(p.getId(),null));}
 @Test void listWithoutFiltersDoesNotSendNullQueryParameters(){when(repo.findAllByOrderByCreatedAtDesc()).thenReturn(List.of());service.list(null,null);verify(repo).findAllByOrderByCreatedAtDesc();}
 @Test void listWithBothFiltersUsesTypedRepositoryMethod(){when(repo.findByStatusAndRequesterNameContainingIgnoreCaseOrStatusAndConceptContainingIgnoreCaseOrderByCreatedAtDesc(any(),anyString(),any(),anyString())).thenReturn(List.of());service.list(RequestStatus.PENDIENTE," equipo ");verify(repo).findByStatusAndRequesterNameContainingIgnoreCaseOrStatusAndConceptContainingIgnoreCaseOrderByCreatedAtDesc(RequestStatus.PENDIENTE,"equipo",RequestStatus.PENDIENTE,"equipo");}
 private CreatePurchaseRequest dto(String n){return new CreatePurchaseRequest("Ana","ana@co.com","Compra","Detalle",new BigDecimal(n),"TI");}}
